parameters.query:
select coalesce(sum(amount_zar) filter (where date = current_date and source_ref ~ '^optimisation-advisor:(pulse|judge|grading|event)'), 0) as day_zar,
 coalesce(sum(amount_zar) filter (where date >= date_trunc('week', current_date)::date and source_ref ~ '^optimisation-advisor:(scan|memo|retro)'), 0) as week_zar
from ops.costs where kind = 'llm' and date >= date_trunc('week', current_date)::date;

