const QUIET = 'All faculties within limits. Nothing to do today. Next weekly memo Monday.';
const QUIET_MONDAY = 'All faculties within limits. Nothing to do today. Weekly memo at 06:00 today.';

const rows = $('Settings').all().map((i) => i.json);
const mode = (rows[0] && rows[0].mode) || 'pulse';
const S = Object.fromEntries(rows.map((r) => [r.key, r.value]));
const c = $('Costs').first().json;
const now = new Date().toISOString();
const cfg = {
  mode, now,
  usd_zar: Number(S.usd_zar || 18),                 // ASSUMPTION until ops.settings.usd_zar is set
  ver: S.wa_graph_version || 'v21.0',               // ASSUMPTION; set ops.settings.wa_graph_version from W27
  twilio: { sid: S.twilio_sid || null, from: S.twilio_voice_from || null },
  build_active: String(S.build_active || 'true') === 'true',
  models: { fast: 'claude-haiku-4-5-20251001', strong: 'claude-sonnet-5-5' },
  rates: { 'claude-haiku-4-5-20251001': { in: 1, out: 5 }, 'claude-sonnet-5-5': { in: 2, out: 10 } },
  caps: { daily: Number(S.opt_daily_cap_zar || 15), weekly: Number(S.opt_weekly_cap_zar || 40), pulse_reserve: 3, memo_reserve: 12, soft: 0.8 },
  spent: { day: Number(c.day_zar || 0), week: Number(c.week_zar || 0) },
};
return [{ json: { cfg, mode, date: ymdSAST(now), weekday: new Date(now).toLocaleDateString('en-ZA', { timeZone: ZA, weekday: 'short' }) } }];

parameters.query:
insert into ops.signals (signal_key, faculty, metric, value, limit_value, run, rule, side, burning, cause, owner, detected_at)
select x.signal_key, x.faculty, x.metric, x.value, x."limit", x.run, x.rule, x.side, x.burning, x.cause, x.owner, now()
from json_to_recordset($1::json) as x(signal_key text, faculty text, metric text, value numeric, "limit" numeric, run text, rule text, side text, burning boolean, cause text, owner text)
where not exists (select 1 from ops.signals s where s.signal_key = x.signal_key);

insert into ops.costs (date, kind, brand_id, broker_id, amount_zar, source_ref)
select x.date::date, x.kind, null, null, round(x.amount_zar::numeric, 2), x.source_ref from json_to_recordset($1::json) as x(date text, kind text, amount_zar numeric, source_ref text)
on conflict (date, kind, brand_id, broker_id, source_ref) do update set amount_zar = ops.costs.amount_zar + excluded.amount_zar;

insert into ops.proposals (pulse_date, faculty, title, metric, forecast, cost_zar, grade, test, kill_rule, mechanism, owner_agent, check_date, ice, source, evidence, status, created_at)
select x.pulse_date::date, x.faculty, x.title, x.metric, x.forecast::text, x.cost_zar, x.grade, x.test, x.kill_rule, x.mechanism, x.owner_agent, x.check_date::date, x.ice::jsonb, x.source, x.evidence, 'proposed', now()
from json_to_recordset($1::json) as x(pulse_date text, faculty text, title text, metric text, forecast json, cost_zar numeric, grade text, test text, kill_rule text, mechanism text, owner_agent text, check_date text, ice json, source text, evidence text)
where not exists (select 1 from ops.proposals p where p.pulse_date = x.pulse_date::date and p.title = x.title)
returning id::text as id, title, metric, forecast, cost_zar, grade, owner_agent, faculty;

